inline std::int32_t itemIdByName(std::string_view raw) {
    std::string s(raw);
    for (auto& c : s) c = static_cast<char>(c >= 'A' && c <= 'Z' ? c - 'A' + 'a' : c);
    if (s.rfind("minecraft:", 0) == 0) s = s.substr(10);
    auto it = itemNameMap().find(s);
    if (it != itemNameMap().end()) return it->second;
    if (!s.empty() && s.find_first_not_of("0123456789") == std::string::npos) {
        const long v = std::stol(s);
        if (v >= 0 && v < static_cast<long>(itemNameMap().size())) return static_cast<std::int32_t>(v);
    }
    return -1;
}

inline std::string itemNameById(std::int32_t id) {
    for (const auto& kv : itemNameMap()) if (kv.second == id) return kv.first;
    return std::to_string(id);
}

